#### **9. ai-translate.ts Provider & Concurrency Usage**

From [tools/i18n-engine/src/ai-translate.ts](tools/i18n-engine/src/ai-translate.ts) lines 57–100:

```typescript
export async function fillUntranslatedEntries(
  poPath: string,
  locale: string,
  provider: ProviderConfig,  // ← Takes provider as parameter
): Promise<void> {
  if (!aiProviderConfigured()) return;  // ← Checks env var, not config.provider
  const entries = parsePo(readFileSync(poPath, "utf8"));
  const untranslated = entries.filter((entry) => !entry.obsolete && entry.msgstr === "");
  if (untranslated.length === 0) return;

  const command = process.env.I18N_TRANSLATION_COMMAND ?? "claude";  // ← Reads env var directly
  const args = commandArgs();  // ← Reads from process.env.I18N_TRANSLATION_COMMAND_ARGS
  const targetLanguage = targetLanguageLabel(locale);

  for (const chunk of chunkEntries(untranslated, provider.batchBudget)) {  // ← Uses provider.batchBudget
    const payload = Object.fromEntries(chunk.map((entry, index) => [String(index), entry.msgid]));
    const prompt = buildBatchTranslationPrompt(targetLanguage, payload);
    const response = await spawnPrompt(command, [...args, "-p"], prompt, `locale '${locale}'`, {
      timeoutMs: provider.timeoutMs,  // ← Uses provider.timeoutMs
    });
    // ... sequential chunk processing (no parallelism)
  }
}
```

**Provider usage:**
- ✅ Uses `provider.batchBudget` for chunk size
- ✅ Uses `provider.timeoutMs` for request timeout
- ❌ Reads command & args from **env vars directly**, not from `config.provider.profiles`
- ❌ **No concurrency/parallelism** — processes chunks sequentially (one `for` loop)

**Helper chunkEntries** (lines 46–58):
```typescript
function chunkEntries(entries: readonly PoEntry[], budget: number): PoEntry[][] {
  const chunks: PoEntry[][] = [];
  let current: PoEntry[] = [];
  let size = 0;
  for (const entry of entries) {
    if (current.length > 0 && size + entry.msgid.length > budget) {
      chunks.push(current);
      current = [];
      size = 0;
    }
    current.push(entry);
    size += entry.msgid.length;
  }
  if (current.length > 0) chunks.push(current);
  return chunks;
}
```

**Skip-if-translated logic** (line 72):
```typescript
const untranslated = entries.filter((entry) => !entry.obsolete && entry.msgstr === "");
```
✅ **Skips entries that already have msgstr** — `--force` would need to flip this.

